const ui124={expanded:true,route:null,wheelAt:0,wheelSign:0,wheelTotal:0,touch:null};
function greeting124(){const h=new Date(ten.now+7*3600000).getUTCHours(),id=isLabel10()?ten.member:me().id,n=String(id).split('').reduce((a,c)=>a+c.charCodeAt(0),0)+new Date(ten.now+7*3600000).getUTCDate();const choices=[h<11?T('Selamat pagi','Good morning'):h<15?T('Selamat siang','Good afternoon'):h<18?T('Selamat sore','Good afternoon'):T('Selamat malam','Good evening'),T('Halo','Hello'),T('Senang bertemu lagi','Good to see you')];return choices[n%choices.length]}
function todayContext124(){if(isLabel10()){const rs=ten.releases.filter(r=>r.member===ten.member),draft=rs.filter(r=>r.status==='draft').length,review=rs.filter(r=>['submitted','review','approved','delivered','followup','revision'].includes(r.status)).length;return T(`${draft} draft dan ${review} rilisan dalam proses saat ini.`,`${draft} drafts and ${review} releases are in progress.`)}if(state.mode==='staff'){const users=staffList122(),jobs=jobs114().filter(j=>!j.closed);return T(`${users.length} anggota tim aktif · ${jobs.length} pekerjaan dalam proses.`,`${users.length} active team members · ${jobs.length} work items in progress.`)}const q=filterItems6('queued').length,done=todayRecords().filter(r=>me().super||r.staff===me().id).length;return T(`${q} pekerjaan dalam antrean · ${done} tahapan selesai hari ini.`,`${q} work items queued · ${done} stages completed today.`)}
hero122=function(){const p=isLabel10()?member10():me(),ins=heroInsight122();return `<section class="dashboard-hero122 hero124" aria-label="${T('Ringkasan dashboard','Dashboard overview')}"><div class="hero-copy122"><h1>${greeting124()},<br><span>${E(p.name)}.</span></h1><p class="hero-context122">${E(todayContext124())}</p></div><div class="hero-insight-wrap122"><button type="button" class="hero-insight122" data-u122="${ins.action}" aria-label="${E(ins.label)}"><span class="insight-title122">${icon('spark')}${T('Wawasan','Insights')}</span><span class="insight-content122"><strong>${ins.number}</strong><span><b>${ins.title}</b><small>${E(ins.detail)}</small></span></span></button></div></section>`};

function platformSummary124(old){const ids=[...old.querySelectorAll('.compare6')].map(e=>e.dataset.id).filter(id=>!me().super||id!=='members').slice(0,5),active=platformData6.find(x=>x[0]==='members');return `<section class="platform6 platform124" aria-label="${T('Ringkasan platform','Platform summary')}"><header class="section-head124"><h2>${T('Ringkasan Platform','Platform Summary')}</h2><small>${T('Perbandingan periode · data simulasi','Period comparison · preview data')}</small></header><div class="platform6-grid">${ids.map(id=>{const x=platformData6.find(x=>x[0]===id);if(!x)return '';const pct=(x[3]-x[4])/x[4]*100,n=new Intl.NumberFormat(state.lang==='id'?'id-ID':'en-US',{maximumFractionDigits:1}).format(Math.abs(pct)),period=T(x[6],x[7]);return `<button type="button" class="compare6 metric124" data-action="v6-metric" data-id="${id}" aria-label="${T('Buka rincian','Open details')} ${T(x[1],x[2])}"><h3>${T(x[1],x[2])}</h3><strong>${x[5]?money(x[3]):fmt(x[3])}</strong><span class="metric-context124">${me().super&&id==='labels'?T(`${fmt(active[3])} label aktif`,`${fmt(active[3])} active labels`):period}</span><span class="metric-foot124"><span><i aria-hidden="true">${pct>=0?'↑':'↓'}</i> ${n}% <small>${T('vs sebelumnya','vs previous')}</small></span>${icon('arrow')}</span></button>`}).join('')}</div></section>`}
function withdrawalCard124(card){const d=withdrawalTotals7(),pct=Math.min(100,Math.max(0,d.paid/d.total*100));card.classList.add('withdraw124');card.innerHTML=`<div class="withdraw-heading124"><div><h2>${T('Penarikan periode ini','Period Withdrawals')}</h2><p>${T('1–18 September / Agustus 2026 · rentang setara','September / August 1–18, 2026 · matched dates')}</p></div><button type="button" class="detail-arrow124" data-action="v6-metric" data-id="withdraw" aria-label="${T('Buka rincian penarikan','Open withdrawal details')}">${icon('arrow')}</button></div><div class="withdraw-body124"><div class="withdraw-amount124"><strong>${money(d.total)}</strong><span>−${T('17,3%','17.3%')} <small>${T('vs periode sebelumnya','vs previous period')}</small></span></div><div class="withdraw-progress124"><div><span>${T('Sudah dibayar','Paid')}</span><strong>${money(d.paid)}</strong></div><div class="payout-track" role="progressbar" aria-label="${T('Bagian penarikan yang telah dibayar','Share of withdrawals paid')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><i style="width:${pct}%"></i></div><div><span>${T('Belum dibayar','Unpaid')}</span><strong>${money(d.unpaid)}</strong></div></div></div>`;return card}

// One geographic projection preserves the proportions of the supplied Natural
// Earth country outline. Unstructured legacy addresses never become map points.
const mapPoint124=([lon,lat])=>[(lon-94)*17,20+(6-lat)*17];
function mapPath124(){const geo=RMIndonesia.features?.[0]?.geometry||RMIndonesia.geometry;return geo.coordinates.map(polygon=>polygon.map(ring=>ring.map((p,i)=>(i?'L':'M')+mapPoint124(p).join(',')).join('')+'Z').join('')).join('')}
memberMapPending=function(){const groups=mapGroups106(),local=ui106.mapCountry==='Indonesia',rows=groups.filter(g=>local?g.local:!g.local).sort((a,b)=>b.members.length-a.members.length),known=groups.filter(g=>g.local&&g.id!=='unknown').reduce((n,g)=>n+g.members.length,0),unknown=groups.find(g=>g.id==='unknown');return `<section class="panel member-map-pending member-map106 geography124" data-widget-id="member-map"><header class="map-header106"><div><h2>${T('Sebaran Member','Member Geography')}</h2><p>${T('Lokasi operasional berdasarkan data label.','Operating locations supplied by labels.')}</p></div><select id="map-country106" aria-label="${T('Cakupan wilayah','Region scope')}"><option value="Indonesia" ${local?'selected':''}>Indonesia</option><option value="world" ${!local?'selected':''}>${T('Luar Indonesia','Outside Indonesia')}</option></select></header><div class="member-geography106 ${local?'':'foreign124'}"><div class="map-table106"><table><thead><tr><th>${local?T('Provinsi','Province'):T('Negara','Country')}</th><th>Label</th><th>${T('Aktif','Active')}</th></tr></thead><tbody>${rows.map(g=>`<tr data-region106="${E(g.id)}"><td>${b106((!g.local?flagPending(g.name)+' ':'')+E(g.name),'region',g.id,'text')}</td><td>${g.members.length}</td><td>${g.members.filter(m=>m.active).length}</td></tr>`).join('')||`<tr><td colspan="3">${T('Belum ada label pada cakupan ini.','No labels in this region yet.')}</td></tr>`}</tbody></table><p class="map-table-note124">${T('Aktif = aktivasi akun disetujui.','Active = account activation approved.')}</p></div>${local?`<div class="map-canvas106"><svg viewBox="0 0 850 340" role="img" aria-label="${T('Sebaran label menurut provinsi Indonesia','Label distribution across Indonesian provinces')}"><path class="island-pending" d="${mapPath124()}"></path>${groups.filter(g=>g.local&&provinceCentersPending[g.id]).map(g=>{const [x,y]=mapPoint124(provinceCentersPending[g.id]),r=4+Math.min(5,g.members.length);return `<g data-region106="${g.id}" data-ui106="region" data-id="${g.id}" tabindex="0" role="button" aria-label="${E(g.name)} · ${g.members.length} label"><circle class="region-hit124" cx="${x}" cy="${y}" r="17"/><circle class="region-dot106" cx="${x}" cy="${y}" r="${r}"/><title>${E(g.name)} · ${g.members.length} label</title></g>`}).join('')}</svg><div class="map-detail106" id="map-detail106">${known?T('Pilih atau sorot titik untuk melihat label di provinsi tersebut.','Select or highlight a marker to see labels in that province.'):T('Belum ada lokasi lengkap untuk dipetakan. Lihat daftar lokasi belum lengkap.','No complete locations are available to map. See the incomplete-location list.')}</div><div class="map-legend124"><span><i></i>${T('Titik provinsi · ukuran mengikuti jumlah label','Province marker · size follows label count')}</span><strong>${known} ${T('terpetakan','mapped')}</strong></div></div>`:''}</div>${unknown||groups.some(g=>!g.local)?`<footer>${unknown?b106(T('Lokasi belum lengkap','Incomplete location')+' · '+unknown.members.length,'region','unknown','text'):''}${groups.filter(g=>!g.local).map(g=>b106(flagPending(g.name)+' '+E(g.name)+' · '+g.members.length,'region',g.id,'text')).join('')}</footer>`:''}</section>`};

function organiseDashboard124(main){if(state.mode!=='platform'||state.page!=='dashboard')return;main.classList.add('dashboard-main124');const legacy=main.querySelector('.legacy-update121');if(legacy){main.prepend(legacy);legacy.querySelector('.legacy-icon121')?.remove();legacy.classList.add('attention9');normalizeAttention109(main)}const nodes=[],attention=[...main.querySelectorAll(':scope>.attention-grid106,:scope>.attention-shell109')],stats=main.querySelector(':scope>.five-stats'),filtered=main.querySelector(':scope>.filtered6');nodes.push(...attention);if(stats)nodes.push(stats);if(filtered)nodes.push(filtered);const grid=document.createElement('div');grid.className='dashboard-rows124';const cards=isLabel10()?['label-releases','label-updates']:['queue','mywork','progress'];for(const key of cards){const card=main.querySelector(`[data-card="${key}"]`);if(card){card.classList.remove('span-4','span-6','span-8','span-12','expanded');card.classList.add('dashboard-card124');grid.append(card)}}if(grid.children.length)nodes.push(grid);const withdraw=main.querySelector('.withdraw6');if(withdraw&&me().super)nodes.push(withdrawalCard124(withdraw));const platform=main.querySelector('.platform6');if(platform){const box=document.createElement('div');box.innerHTML=platformSummary124(platform);nodes.push(box.firstElementChild)}const map=main.querySelector('.member-map106');if(map&&super114())nodes.push(map);main.replaceChildren(...nodes);stats?.querySelectorAll('.featured').forEach(e=>e.classList.remove('featured'));if(!isLabel10()){const waiting=stats?.querySelector('[data-action="v6-filter"][data-id="waiting"]')?.closest('.stat6')?.querySelector('small');if(waiting)waiting.textContent=T('Jawaban atau perbaikan','Response or correction')}if(isLabel10())stats?.querySelectorAll('[data-ten="summary102"]').forEach(b=>b.setAttribute('aria-expanded',String(labelSummary102===Number(b.dataset.id))));}

let resize124=null;
function syncMasthead124(){const box=document.querySelector('.masthead124'),bar=box?.querySelector('.header');if(!box||!bar)return;document.documentElement.style.setProperty('--bar-height124',bar.getBoundingClientRect().height+'px');document.documentElement.style.setProperty('--masthead-height124',box.getBoundingClientRect().height+'px');box.dataset.expanded=String(ui124.expanded);}
function setHero124(expanded){const box=document.querySelector('.masthead124'),clip=box?.querySelector('.hero-clip124');if(!clip||ui124.expanded===expanded)return false;ui124.expanded=expanded;box.classList.toggle('is-collapsed124',!expanded);clip.inert=!expanded;clip.setAttribute('aria-hidden',String(!expanded));box.querySelector('.masthead-key124')?.setAttribute('aria-expanded',String(expanded));syncMasthead124();return true}
function mountMasthead124(app,header,hero){app.querySelector('.masthead-paint123')?.remove();const frame=document.createElement('div');frame.className='masthead124';app.prepend(frame);frame.append(header);header.classList.add('header124');const search=header.querySelector('[data-action="search"]');if(search){search.innerHTML=icon('search')+`<span>${T('Cari','Search')}</span>`;search.setAttribute('aria-expanded',String(!!document.querySelector('.search-popover')));search.setAttribute('aria-controls','header-popover')}if(hero){frame.classList.add('has-hero124');const clip=document.createElement('div');clip.className='hero-clip124';const inner=document.createElement('div');inner.className='hero-inner124';frame.append(clip);clip.append(inner);inner.append(hero);frame.classList.toggle('is-collapsed124',!ui124.expanded);clip.inert=!ui124.expanded;clip.setAttribute('aria-hidden',String(!ui124.expanded));const key=document.createElement('button');key.type='button';key.className='masthead-key124';key.dataset.u124='hero';key.setAttribute('aria-expanded',String(ui124.expanded));key.textContent=T('Buka atau tutup ringkasan dashboard','Expand or collapse dashboard overview');header.append(key)}resize124?.disconnect();if(typeof ResizeObserver==='function'){resize124=new ResizeObserver(syncMasthead124);resize124.observe(frame);resize124.observe(header)}syncMasthead124()}

function innerScroll124(target){if(!(target instanceof Element))return true;if(target.closest('.side5,dialog,.header-popover,.drawer,.drawer8,.module-tabs,.tabs,input,textarea,select,[contenteditable=true]'))return true;for(let e=target;e&&e!==document.body;e=e.parentElement){if(e.matches('#main,.shell,.workspace-body122,#app,.masthead124,.hero-clip124,.hero-inner124'))continue;const s=getComputedStyle(e);if(/auto|scroll/.test(s.overflowY)&&e.scrollHeight>e.clientHeight+2)return true}return false}
window.addEventListener('wheel',e=>{if(!document.querySelector('.hero-clip124')||e.ctrlKey||e.metaKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||innerScroll124(e.target))return;const now=performance.now(),sign=Math.sign(e.deltaY);if(now-ui124.wheelAt>180||sign!==ui124.wheelSign)ui124.wheelTotal=0;ui124.wheelAt=now;ui124.wheelSign=sign;ui124.wheelTotal+=Math.abs(e.deltaY)*(e.deltaMode===1?16:1);if(ui124.wheelTotal<12)return;if(setHero124(sign<0)){e.preventDefault()}},{passive:false});
window.addEventListener('touchstart',e=>{ui124.touch=e.touches.length===1&&!innerScroll124(e.target)?{x:e.touches[0].clientX,y:e.touches[0].clientY,handled:false}:null},{passive:true});
window.addEventListener('touchmove',e=>{const t=ui124.touch;if(!t||t.handled||e.touches.length!==1||!document.querySelector('.hero-clip124'))return;const dx=t.x-e.touches[0].clientX,dy=t.y-e.touches[0].clientY;if(Math.abs(dy)<24||Math.abs(dx)>Math.abs(dy))return;t.handled=true;if(setHero124(dy<0))e.preventDefault()},{passive:false});
window.addEventListener('touchend',()=>ui124.touch=null,{passive:true});
window.addEventListener('keydown',e=>{if(e.defaultPrevented||e.altKey||e.ctrlKey||e.metaKey||innerScroll124(e.target)||!document.querySelector('.hero-clip124'))return;if((e.key==='PageDown'||e.key==='PageUp')&&setHero124(e.key==='PageUp'))e.preventDefault()});
window.addEventListener('click',e=>{const b=e.target.closest('[data-u124="hero"]');if(b){e.preventDefault();setHero124(!ui124.expanded)}},true);

